/** The Arabic sentence as one string for the voice (wa is written attached to the next word). */
export function phraseScript(tokens: string[]): string {
  let s = '';
  tokens.forEach((id) => {
    const b = BLOCKS[id];
    s += b.arabic + (b.clitic ? '' : ' ');
  });
  return s.trim();
}
